package engine

import (
	"net/netip"
	"os"
	"strings"
	"testing"
	"time"
)

// The app bundles app/src/main/assets/country_ranges.txt, generated by
// scripts/geoip/generate_country_ranges.py. Kotlin hands the engine the lines
// of whichever countries the user ticked, so every combination, up to all of
// them at once, must parse. A data refresh that breaks the engine's rules
// would otherwise show up as a failed Connect on a user's phone.
const shippedCountryData = "../app/src/main/assets/country_ranges.txt"

func shippedCountryPrefixes(t *testing.T) map[string][]string {
	t.Helper()
	raw, err := os.ReadFile(shippedCountryData)
	if err != nil {
		t.Fatalf("read the shipped country data: %v", err)
	}
	byCountry := map[string][]string{}
	for _, line := range strings.Split(string(raw), "\n") {
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		fields := strings.Fields(line)
		if len(fields[0]) != 2 {
			t.Fatalf("malformed country line %.40q", line)
		}
		byCountry[fields[0]] = append(byCountry[fields[0]], fields[1:]...)
	}
	return byCountry
}

func TestShippedCountryDataParsesWholeAndPerCountry(t *testing.T) {
	byCountry := shippedCountryPrefixes(t)
	if len(byCountry) < 200 {
		t.Fatalf("expected a world of countries, got %d", len(byCountry))
	}

	var all []string
	total := 0
	for code, prefixes := range byCountry {
		list, err := parseCountryBlocklist(strings.Join(prefixes, " "))
		if err != nil {
			t.Fatalf("%s does not parse: %v", code, err)
		}
		if list == nil || list.entries != len(prefixes) {
			t.Fatalf("%s: parsed %v entries, want %d", code, list, len(prefixes))
		}
		all = append(all, prefixes...)
		total += len(prefixes)
	}

	start := time.Now()
	world, err := parseCountryBlocklist(strings.Join(all, " "))
	if err != nil {
		t.Fatalf("selecting every country at once must parse: %v", err)
	}
	if world.entries != total {
		t.Fatalf("world list has %d entries, want %d", world.entries, total)
	}
	if total >= maxBlockPrefixes {
		t.Fatalf("the data (%d prefixes) has outgrown the engine's %d-prefix limit", total, maxBlockPrefixes)
	}
	t.Logf("parsed %d prefixes (%d IPv4 + %d IPv6 ranges after merging) in %v",
		total, len(world.v4), len(world.v6), time.Since(start))
}

func TestShippedCountryDataBlocksNorthKoreaAndNotItsNeighbours(t *testing.T) {
	// North Korea's only registry delegation is 175.45.176.0/22; the docs and
	// UI copy say so, so a change here is worth noticing.
	kp := shippedCountryPrefixes(t)["KP"]
	if len(kp) != 1 || kp[0] != "175.45.176.0/22" {
		t.Fatalf("KP prefixes = %v", kp)
	}
	list := mustParseBlocklist(t, strings.Join(kp, " "))
	for ip, want := range map[string]bool{
		"175.45.175.255": false,
		"175.45.176.0":   true,
		"175.45.179.255": true,
		"175.45.180.0":   false,
	} {
		if got := list.contains(netip.MustParseAddr(ip)); got != want {
			t.Errorf("contains(%s) = %v, want %v", ip, got, want)
		}
	}
}
